"""Held-out author expectations: exclude this file from blinded review. No inference."""
from pathlib import Path
import json,hashlib,collections
B=Path(__file__).parent;R=B.parents[2];S=B/'heldout_ds_sources'
T={p.stem:p.read_bytes().decode('utf-8')for p in S.glob('*.txt')}
M={r['id']:r for r in json.loads((S/'manifest.json').read_bytes())if r['status']=='captured'}
cases=[];labels=[]
def span(s,start,end=None):
 t=T[s];a=t.index(start);b=t.index(end,a)if end else len(t);v=t[a:b].strip();a=t.index(v,a);p=S/(s+'.txt');return v,{'path':str(p.relative_to(R)),'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'start':a,'end':a+len(v)}
def pair(s,start,end,definition,claim,support,dr,sr,edge='express_definition_or_operative_rule',support_span=None,cluster=None):
 passage,source=span(s,start,end)
 for task,expected,reason in [('definition_present',definition,dr),('supports_claim',support,sr)]:
  state={'passage':passage}if task=='definition_present'else{'claim':claim,'text':passage};field='passage'if task=='definition_present'else'text';sel=source
  if task=='supports_claim'and support_span:state['text'],sel=span(s,*support_span)
  cid=f'hds{len(cases)+1:03}';row={'id':cid,'task':task,'family':M[s]['family'],'source_cluster':cluster or s+':selected-issue','authority_lineage':M[s]['authority_lineage'],'state':state,'sources':{field:sel}}
  cases.append(row);labels.append({'id':cid,'expected':expected,'reason':reason,'edge_case':edge,'downstream_failure':'False extraction/omitted meaning'if task=='definition_present'else'Unsupported legal proposition adopted or supported proposition discarded'})
  (B/'heldout_ds.cases.json').write_text(json.dumps({'cases':cases},indent=2,ensure_ascii=False)+'\n');(B/'heldout_ds.author_labels.json').write_text(json.dumps({'cases':labels},indent=2,ensure_ascii=False)+'\n')
